SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prosrc FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN ('fin_rectification_apply','fin_post_document','fin_post_document_safe','fin_post_document_annulment','fin_apply_opening_balance','reset_store_data','delete_received_service_draft','fin_generation_create','fin_generation_build','fin_generation_validate','fin_trg_transactions') ORDER BY p.proname, args;
